  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Giếng nước của làng\":\nNăm ấy, trời nắng hạn suốt ba tháng. Ruộng nứt nẻ, cây cối héo khô. Dân làng lo lắng vì giếng sắp cạn. Một buổi sáng, các cụ già họp bàn cùng dân làng. Mọi người quyết định đào thêm một cái giếng mới ở chân đồi. Trai làng đào, gái làng gánh đất, trẻ con mang nước uống. Đến chiều tối, dòng nước mát lành đã trào lên. Cả làng mừng rỡ.\n\nNăm ấy, làng gặp chuyện gì?"}'::jsonb, '["nắng hạn kéo dài","lũ lụt","bão lớn"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
