  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Thác nước trong rừng\":\nSâu trong rừng có một ngọn thác cao. Từ xa đã nghe tiếng nước đổ ào ào. Dòng nước trắng xoá từ vách đá lao xuống, tung bọt như mây bay. Dưới chân thác là một hồ nước trong xanh. Buổi sớm, sương mù bao phủ, ngọn thác như dải lụa mờ ảo. Buổi trưa, nắng chiếu vào bụi nước tạo thành cầu vồng nhỏ. Ai đến đây cũng không muốn về.\n\nDưới chân thác có gì?"}'::jsonb, '["một hồ nước trong xanh","một ngôi làng","một cánh đồng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
