  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Đôi tay cùng làm\":\nTay Phải hay khoe: \"Tớ cầm bút viết, cầm thìa ăn cơm, việc gì cũng giỏi!\" Tay Trái im lặng. Một hôm, Tay Phải bị đau, phải băng lại. Tay Trái cố gắng cầm thìa, cầm bút bằng những ngón tay còn vụng. Lúc buộc dây giày, Tay Trái loay hoay mãi mới xong. Tay Phải hiểu ra: \"Thì ra bạn cũng vất vả lắm. Từ nay chúng mình cùng làm nhé!\"\n\nTay Phải hay khoe điều gì?"}'::jsonb, '["mình làm việc gì cũng giỏi","mình đẹp nhất","mình khoẻ nhất"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
