  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Ngôi nhà chung của buôn\":\nGiữa buôn làng Tây Nguyên có một ngôi nhà rông cao vút. Mái nhà nhọn như lưỡi rìu dựng ngược lên trời. Nhà rông là nơi dân làng họp bàn việc chung, tổ chức lễ hội. Tối tối, các cụ già kể cho con cháu nghe sự tích của buôn. Già làng thường nói: \"Nhà rông là trái tim của buôn làng.\" Ai đi xa trở về cũng ghé nhà rông đầu tiên.\n\nNhà rông ở vùng nào?"}'::jsonb, '["Tây Nguyên","đồng bằng Bắc Bộ","ven biển"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
