  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Chú rô-bốt nhặt rác\":\nỞ công viên gần nhà Huy mới có một chú rô-bốt nhặt rác. Chú cao bằng một bạn lớp ba, có hai tay kẹp và một cái thùng trên lưng. Chú đi chầm chậm, nhặt vỏ chai, túi ni lông bỏ vào thùng. Huy hỏi bố: \"Người ta làm rô-bốt để làm gì hả bố?\" Bố đáp: \"Để giúp con người làm việc và giữ môi trường sạch đẹp.\" Huy tự nhủ: mình cũng sẽ không vứt rác bừa bãi.\n\nChú rô-bốt làm việc gì?"}'::jsonb, '["nhặt rác trong công viên","tưới cây","bán hàng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
