  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Những việc nhỏ của Mai\":\nMai muốn bảo vệ Trái Đất bằng những việc nhỏ. Đánh răng xong, Mai khoá vòi nước ngay. Ra khỏi phòng, Mai tắt đèn, tắt quạt. Đi chợ với mẹ, Mai mang theo làn nhựa thay cho túi ni lông. Mai còn rủ các bạn trồng cây xanh ở góc sân trường. Mai bảo: \"Mỗi người một việc nhỏ, Trái Đất sẽ xanh hơn!\"\n\nĐánh răng xong, Mai làm gì?"}'::jsonb, '["khoá vòi nước ngay","để nước chảy","đi ngủ"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
