  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Người bạn đến từ xa\":\nLớp em đón một vị khách đặc biệt: cô Ma-ri-a đến từ nước Ý. Cô là nhà khoa học nghiên cứu về các loài chim. Cô kể rằng có những loài chim bay hàng nghìn ki-lô-mét qua nhiều nước để tránh rét. Cô nói: \"Bầu trời không có biên giới. Trái Đất là mái nhà chung của muôn loài.\" Cả lớp vỗ tay. Em mơ ước lớn lên cũng sẽ đi khắp nơi tìm hiểu thiên nhiên.\n\nCô Ma-ri-a đến từ nước nào?"}'::jsonb, '["nước Ý","nước Pháp","nước Nhật"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
