  insert into public.questions (lesson_id, question_type, prompt, options, skill_code, difficulty, time_limit_sec, sort_order, status, form_id, outcome_id) values (v_lesson, 'single_choice', '{"text":"Đọc bài \"Lá thư gửi lớp Ba\":\nNgày cuối năm học, cô giáo đọc cho cả lớp nghe lá thư của bạn Nhật, người đã chuyển trường. Nhật viết: \"Tớ nhớ các cậu lắm! Nhớ những giờ ra chơi đá cầu, những buổi trồng cây ở vườn trường.\" Cả lớp lặng đi. Rồi lớp trưởng đề nghị: \"Chúng mình cùng viết thư trả lời Nhật nhé!\" Mỗi bạn viết một dòng. Lá thư dài như một dải lụa nhiều màu sắc.\n\nAi viết thư gửi cả lớp?"}'::jsonb, '["bạn Nhật","cô giáo","lớp trưởng"]'::jsonb, null, 1, 40, 1, 'draft', (select id from public.exercise_forms where code = 'TV.DOCHIEU'), (select id from public.learning_outcomes where code = 'V3.DOC.01')) returning id into v_q;
