  insert into public.question_keys (question_id, answer_key, explanation, solution) values (v_q, '{"pairs":{"How are you?":"Fine, thank you.","What''s this?":"It''s a nose.","Is this our library?":"Yes, it is."}}'::jsonb, '{"text":"How are you? – Fine, thank you.; What''s this? – It''s a nose.; Is this our library? – Yes, it is."}'::jsonb, '{"text":"\"How are you?\" → \"Fine, thank you.\" (Bạn khoẻ không? – Tớ khoẻ, cảm ơn bạn.); \"What''s this?\" → \"It''s a nose.\" (Đây là cái gì? – Đó là cái mũi.); \"Is this our library?\" → \"Yes, it is.\" (Đây có phải thư viện của chúng mình không? – Đúng vậy.)"}'::jsonb);
